-- The Malay (ms-MY) edition of the five product category pages: the page
-- header (product_category_i18n), the "how to choose" guide, the reasons to
-- buy, the FAQ, and the product cards the grid shows (product_i18n), plus the
-- spec bullets each signature band prints (product_spec_i18n).
--
-- Hand-authored, translated row for row from category-content.sql and the
-- product rows: same category, same position, same figure. Figures are
-- language-free and are copied, never re-derived; only a figure_unit that is a
-- word is translated ('place settings' -> 'tetapan tempat'), never L, °C,
-- m³/h, Pa, dB or kW. Ids are resolved by slug.
--
-- The name is load order, not taste: db-build.mjs runs files outside its ORDER
-- list alphabetically, and four published products are inserted late, the
-- DWID3 pair in product-images-2026-08.sql and the V959 and VH-IC9-LA in
-- new-products-2026-08.sql. A name sorting before those ('i18n-...') fails
-- the build on a NULL product_id. 't' runs after them and after
-- category-content.sql, so every row this file mirrors already exists.
--
-- Malaysian Malay throughout, not Indonesian: dapur gas, penyedut, kuali,
-- ketuhar, pinggan mangkuk. Each page's H1, title and description follow its
-- keyword_map row (keyword-map.sql): the Malay term leads, the English
-- loanword people also type (cooker hood, dishwasher) rides in the title.
--
-- Deliberately NOT carried over from the English: prices, running-cost,
-- energy and water claims, and who arranges installation. Where an English
-- row makes one, the Malay row keeps the rest and drops that clause.
--
-- Links stay on the English pages they point to, except the two hood guides
-- that have Malay editions: types-of-range-hoods -> /ms/panduan-membeli/hood-dapur/
-- and the ducted-or-ductless guide -> /ms/panduan-membeli/hood-dapur-tanpa-tebuk-dinding/.

-- ── category headers ───────────────────────────────────────────────────────
-- Slugs and names are fixed by the URL plan; the slug is the keyword.
INSERT INTO product_category_i18n
  (category_id, lang, slug, name, h1, seo_title, meta_description, intro_md, signature_image_alt) VALUES
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY',
   'hood-dapur', 'Hood Dapur',
   'Hood Dapur Berkuasa untuk Rumah Malaysia yang Bebas Asap',
   'Hood Dapur & Cooker Hood di Malaysia | VATTI Malaysia',
   'Hood dapur VATTI di Malaysia, dibandingkan pada tekanan sedutan, bunyi dan aliran udara terukur. Padankan dengan masakan kuali anda. Waranti motor 10 tahun.',
   'Direka untuk masakan kuali berapi tinggi dan penggunaan minyak yang banyak, hood dapur VATTI menyedut asap dengan kuat, menapis gris dengan berkesan dan beroperasi dengan senyap, sesuai untuk rumah, kondominium dan dapur terbuka moden di Malaysia.',
   'Hood dapur VATTI V929 menyedut wap dari stik yang sedang dibakar dalam kuali di atas dapur gas.'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY',
   'dapur-gas', 'Dapur Gas',
   'Dapur Gas Terbina Dalam yang Berkuasa dan Tepat untuk Masakan Asia Moden',
   'Dapur Gas Tanam & Terbina Dalam di Malaysia | VATTI',
   'Dapur gas terbina dalam VATTI di Malaysia, serta dapur seramik dan induksi, untuk masakan Asia berapi tinggi. Bandingkan kuasa tungku dan ciri keselamatannya.',
   'Direka untuk masakan kuali berapi tinggi dan hidangan keluarga setiap hari, dapur gas dan dapur seramik terbina dalam kami memberi kawalan api yang berkuasa, perlindungan keselamatan yang lengkap dan kemasan yang sebati dengan dapur anda.',
   'Dapur VATTI C861G terpasang pada kaunter marmar, kaca kelabu bertekstur berus dan jalur sentuhnya menyala, di antara pembakar roti, cerek dan papan pemotong.'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY',
   'ketuhar-kombi', 'Ketuhar Kombi',
   'Ketuhar Kombi dan Ketuhar Stim untuk Masakan Berkuasa, Sihat dan Pintar di Malaysia',
   'Ketuhar Kombi & Ketuhar Stim Terbina Dalam | VATTI Malaysia',
   'Ketuhar kombi (combi oven) VATTI di Malaysia: ketuhar terbina dalam 70L yang mengukus, membakar dan menggoreng udara, serta mod nasi, bubur dan 3 tahap stim.',
   'Ketuhar terbina dalam untuk dapur rumah yang mengukus sekerap ia membakar. Tiga ketuhar bersaiz penuh yang boleh menggoreng udara, dua daripadanya ketuhar kombi dengan tiga tahap stim serta mod untuk nasi dan bubur, dan sebuah ketuhar gelombang mikro terbina dalam 25L.',
   'Ketuhar kombi terbina dalam VATTI dipasang pada paras mata dalam deretan kabinet walnut gelap, paparannya menyala di sebelah dinding belakang marmar.'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY',
   'mesin-basuh-pinggan', 'Mesin Basuh Pinggan',
   'Mesin Basuh Pinggan Canggih untuk Pencucian yang Bersih dan Mudah di Malaysia',
   'Mesin Basuh Pinggan (Dishwasher) di Malaysia | VATTI',
   'Mesin basuh pinggan VATTI di Malaysia untuk 17 dan 20 tetapan tempat: basuhan 75°C untuk periuk berminyak, pensterilan UVC dan simpanan segar sehingga 7 hari.',
   'Dua mesin basuh pinggan bersaiz untuk isi rumah yang besar, pada 17 dan 20 tetapan tempat. Kedua-duanya membasuh pada 75°C untuk menanggalkan minyak masakan, mensteril dengan UVC, dan memastikan muatan yang siap kekal kering sehingga tujuh hari di dapur yang lembap.',
   'Mesin basuh pinggan VATTI DWBB7 terbina dalam deretan kabinet kelabu, pintunya terbuka dan raknya bercahaya, di dapur berdinding belakang marmar.'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY',
   'penapis-air', 'Penapis Air',
   'Penapis Air Satu Paip dan Dispenser Air Panas Segera',
   'Penapis Air & Dispenser Air Panas Satu Paip | VATTI Malaysia',
   'Penapis air satu paip VATTI di Malaysia: penapisan membran RO pelbagai peringkat dan dispenser air panas pada empat suhu, dari sejuk hingga 100°C, di sinki.',
   'Nikmati air minuman yang bersih dan selamat dengan satu sentuhan. Sistem penapis air satu paip kami menggabungkan penapisan membran RO, penulenan pelbagai peringkat dan kawalan suhu yang tepat untuk kemudahan setiap hari.',
   'Penapis air VATTI WDHG01 dan pemanas V818WD di atas kaunter marmar, dengan paip One Tap keluli tahan karat dipasang di sinki bersebelahan.');

-- ── hood dapur ─────────────────────────────────────────────────────────────
-- Guide 4 drops "budget for filter replacement" (running cost); reason 4 drops
-- "draws less power" (energy); FAQ 3 drops "preferably the authorised dealer
-- you bought it from" (installation arrangement). FAQ 1 and 2 link to the
-- Malay editions of the two hood guides.
INSERT INTO category_guide (category_id, lang, position, heading, body_md, figure, figure_unit) VALUES
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 1,
   'Mulakan dengan sepuluh pertukaran udara sejam',
   'Dapur biasa di Malaysia memerlukan sekitar 650 hingga 800 m³/h untuk menukar udaranya sepuluh kali sejam. Setiap hood di halaman ini dinilai jauh melebihi angka itu pada aliran bebas, sebab itu aliran udara sahaja tidak dapat memberitahu anda model mana yang patut dibeli.',
   '650-800', 'm³/h'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 2,
   'Tekanan statik yang membezakan setiap model',
   'Aliran udara diukur tanpa sebarang halangan. Tekanan statik ialah apa yang masih tinggal apabila udara perlu naik melalui saluran menegak atau membelok dua penjuru. Saluran pendek ke dinding luar: hujung bawah julat sudah memadai. Bangunan tinggi atau saluran panjang melalui siling: pilih hujung atas julat.',
   '420-1,700', 'Pa'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 3,
   'Bersaluran, jika bangunan membenarkannya',
   'Hood bersaluran menolak asap, wap dan gris ke luar dan tidak pernah memulangkannya ke dapur. Inilah susunan yang lebih berkesan untuk masakan kuali berapi tinggi, dan pilihan yang tepat setiap kali saluran boleh sampai ke dinding luar.',
   NULL, NULL),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 4,
   'Tanpa saluran, apabila bangunan tidak membenarkannya',
   'Hood edaran semula menapis udara dan memulangkannya ke dalam bilik. Ia pilihan praktikal di tempat yang tidak membenarkan bolong ke luar. Jangkakan haba dan kelembapan kekal di dapur bersama anda.',
   NULL, NULL),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 5,
   'Badan nipis dan tersembunyi untuk dapur kondominium',
   'Hood nipis atau tersembunyi menyedut sekuat model cerobong tanpa menguasai ruang. Badan tersembunyi duduk rata di dalam kabinet di atas dapur, dan itulah yang mengekalkan pandangan yang jelas merentasi pulau dapur terbuka.',
   NULL, NULL),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 6,
   'Ikut saiz dapur, bukan saiz dinding',
   'Hood mesti sekurang-kurangnya selebar dapur, atau asap akan terlepas di tepinya walau sekuat mana motor menyedut. Padankan dengan lebar dapur, dan apabila saiznya jatuh di antara dua model, pilih yang lebih besar.',
   NULL, NULL);

INSERT INTO category_reason (category_id, lang, position, title, body_md, figure, figure_unit, icon) VALUES
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 1,
   'Aliran udara dan tekanan, bukan aliran udara sahaja',
   'Aliran udara membersihkan asap. Tekanan statik pula yang terus membersihkannya melalui saluran yang membelok, naik dan panjang. Julat ini mencapai 1,700 Pa, iaitu tahap di mana pemasangan di bangunan tinggi tidak lagi menjadi kompromi.',
   '1,700', 'Pa', 'airflow'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 2,
   'Gris ditangkap berlapis-lapis',
   'Pemisahan minyak mencapai 92% pada model yang lebih tinggi. Model PM2.5 menambah penulenan udara selepas peringkat gris, jadi udara yang keluar dari dapur lebih bersih daripada yang dapat diberi oleh penapis sahaja.',
   '92', '%', 'filtration'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 3,
   'Senyap untuk jumlah udara yang disedut',
   'Bunyi yang diukur merentasi julat ini ialah dari 46.5 dB hingga 54 dB. Ia datang daripada reka bentuk saluran aerodinamik dan penebat motor, bukan daripada kipas yang lebih kecil: hood paling senyap di sini juga antara yang paling kuat.',
   '46.5', 'dB', 'noise'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 4,
   'Motor tanpa berus',
   'Motor BLDC mengekalkan sedutan pada kelajuan yang lebih rendah dan kekal senyap walaupun usianya meningkat. Tapis senarai di atas mengikut motor untuk melihat model mana yang menggunakannya.',
   NULL, NULL, 'motor'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 5,
   'Pembersihan automatik yang panas',
   'Kitaran wap suhu tinggi dan basuhan turbo menanggalkan minyak dari dinding ruang sebelum ia mengeras. Gris ialah sebab hood kehilangan sedutan pada tahun ketiga. Hampir tidak pernah motornya.',
   NULL, NULL, 'clean'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 6,
   'Kawalan yang boleh digunakan dengan tangan berminyak',
   'Lambai tangan dan bukannya menyentuh panel. Model terpilih menambah WiFi dan pautan ke dapur gas, jadi sedutan mengikut api dan berhenti sendiri selepas anda selesai memasak.',
   NULL, NULL, 'controls');

INSERT INTO category_faq (category_id, lang, position, question, answer_md) VALUES
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 1,
   'Jenis hood dapur yang mana lebih baik?',
   'Hood lekap dinding dan hood pulau ialah pilihan biasa untuk pengudaraan yang kuat. Soalan yang lebih penting di dapur Malaysia ialah bersaluran atau tanpa saluran: membuang udara ke luar lebih baik daripada mengedarkannya semula setiap kali bangunan membenarkan. Panduan kami tentang [hood dapur tanpa tebuk dinding](/ms/panduan-membeli/hood-dapur-tanpa-tebuk-dinding/) menerangkan bila setiap satunya pilihan yang tepat.'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 2,
   'Apa yang perlu dilihat semasa membeli hood dapur?',
   'Kuasa sedutan, tekanan statik, tahap bunyi, dan badan yang sekurang-kurangnya selebar dapur anda. Sensor lambaian tangan dan pembersihan automatik hanya penting selepas empat perkara itu. [Panduan jenis hood dapur](/ms/panduan-membeli/hood-dapur/) kami menerangkannya satu per satu.'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 3,
   'Siapa yang patut memasang hood dapur?',
   'Pemasang profesional. Saluran, ketinggian pemasangan dan kerja elektrik semuanya mempengaruhi prestasi hood, dan memasangnya sendiri boleh membatalkan waranti.'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 4,
   'Adakah hood dapur menghilangkan bau?',
   'Ya. Penapis gris menangkap minyak dan aliran udara membawa bau keluar bersamanya. Model dengan penulenan PM2.5 dan pengurangan bau pergi lebih jauh, sehingga 97% pada V938 dan V960.'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 5,
   'Berapakah kuasa sedutan yang baik untuk hood dapur?',
   'Sasarkan pertukaran udara dapur sekurang-kurangnya sepuluh kali sejam, iaitu kira-kira 650 hingga 800 m³/h untuk dapur biasa. Setiap hood di sini melepasi angka itu dengan selesa, jadi gunakan tekanan statik untuk memilih antara mereka.'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 6,
   'Apakah hood dapur pintar?',
   'Hood dengan sensor lambaian tangan, penutupan bermasa dan, pada model teratas, WiFi serta pautan automatik ke dapur gas. Hood menaikkan kelajuannya sendiri apabila api dibesarkan dan terus berjalan beberapa minit selepas anda berhenti memasak.'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 7,
   'Adakah semua hood dapur bising?',
   'Tidak. Bunyi bergantung pada reka bentuk motor dan saluran, dan perbandingan yang berguna ialah angka dB yang diukur, bukan bahasa pemasaran. Apa sahaja dalam julat 45 hingga 55 dB cukup senyap untuk berbual sambil memasak.'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 8,
   'Hood dapur VATTI yang mana paling senyap?',
   '[Aetheris V929](/vatti-aetheris-series-cooker-hood-v929/) pada 46.5 dB, dan ia antara penyedut terkuat dalam julat ini pada 3,125 m³/h. Yang paling senyap seterusnya ialah [Stellar V960](/vatti-stellar-series-cooker-hood-v960/) dan [Hidden V938](/vatti-hidden-series-range-hood-v938/) pada 48 dB, dan kedua-duanya menyedut lebih kuat lagi.'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 9,
   'Saiz hood dapur yang bagaimana saya perlukan?',
   'Sekurang-kurangnya selebar dapur anda. Hood yang lebih sempit daripada permukaan memasak membiarkan asap terlepas di tepinya walau sekuat mana pun ia, jadi jika ragu-ragu, pilih badan yang lebih besar.'),
  ((SELECT id FROM product_category WHERE slug = 'kitchen-hood-in-malaysia'), 'ms-MY', 10,
   'Berapa lama hood dapur sepatutnya tahan?',
   'Sepuluh hingga lima belas tahun dengan penjagaan yang betul. [Bersihkan penapis](/tips-tricks/how-to-clean-kitchen-hood-filter/) mengikut jadual dan jalankan kitaran pembersihan automatik: kesan gris yang terkumpul, bukan kehausan, yang menghilangkan sedutan.');

-- ── dapur gas ──────────────────────────────────────────────────────────────
-- Reason 2's title drops "less wasted gas" (an energy claim); the published
-- 73% efficiency figure stays, as a spec. FAQ 10 drops "the authorised dealer
-- you buy from will arrange it" (installation arrangement).
INSERT INTO category_guide (category_id, lang, position, heading, body_md, figure, figure_unit) VALUES
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 1,
   'Mulakan dengan kuasa tungku',
   'Masakan Malaysia ialah masakan berapi tinggi, dan kadar kuasa tungku menentukan sama ada kuali dapat mencapai haba itu. Dapur gas di halaman ini mempunyai tungku utama dari 3.8 kW hingga 6 kW. Dari 4.8 kW ke atas, haba cukup untuk mengekalkan wok hei sepanjang satu tumisan penuh; di bawahnya sesuai untuk isi rumah yang kebanyakannya merebus dan mereneh.',
   '3.8-6', 'kW'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 2,
   'Ukur lubang potongan, bukan dapurnya',
   'Dapur gas dibeli untuk dimuatkan ke dalam lubang yang sudah ada, jadi bukaan pada kaunter menyingkirkan lebih banyak model berbanding mana-mana spesifikasi. Kedua-dua dapur Flexi menerima bukaan selebar 650 hingga 710 mm dan sedalam 350 hingga 400 mm, dan itulah yang membolehkannya dimuatkan ke kaunter yang dipotong untuk jenama lain.',
   '650-710', 'mm'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 3,
   'Gas, untuk kuali',
   'Gas bertindak balas sebaik sahaja tombol dipusing, bertukar dari api penuh ke api kecil serta-merta, dan terus berfungsi semasa bekalan elektrik terputus. Ia masih pilihan yang tepat untuk sesiapa yang menumis, dan sembilan daripada sebelas dapur di sini ialah dapur gas.',
   NULL, NULL),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 4,
   'Seramik elektrik, untuk permukaan rata',
   'Dapur seramik memanaskan secara sekata, tiada api terbuka, dan boleh dilap sekali lalu kerana seluruh permukaannya rata. Zonnya mencapai 2,200 W, dengan kawalan sentuh dan amaran haba baki. Pilih ia untuk dapur yang memasak dengan lebih perlahan, atau di tempat yang tiada bekalan gas.',
   NULL, NULL),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 5,
   'Keselamatan yang berfungsi tanpa anda',
   'Setiap dapur gas di sini mempunyai alat keselamatan yang memutuskan gas apabila api padam. Kebanyakannya menambah kunci kanak-kanak pada tombol kawalan, dan model yang lebih baharu menambah pemutus kering bakar dan pemutus terma serta sensor yang mematikan tungku apabila tiada apa-apa di atasnya. Dapur seramik mempunyai kunci kanak-kanak, pemutus panas lampau dan amaran haba baki.',
   NULL, NULL),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 6,
   'Kaca atau keluli tahan karat',
   'Kaca terbaja mudah dilap dan sesuai untuk dapur moden, dan C836G menambah salutan nano supaya gris mudah tertanggal. Keluli tahan karat lebih tahan haba dan hentakan, sebab itu Professional C720S diperbuat daripadanya. Kebanyakan model duduk di atas penyokong besi tuang yang cukup berat untuk menahan kuali yang penuh dengan stabil. [Panduan membeli dapur gas](/buying-guide/glass-vs-stainless-gas-hob-which-gas-hob-are-best/) kami menimbang kedua-duanya dengan lengkap.',
   NULL, NULL);

INSERT INTO category_reason (category_id, lang, position, title, body_md, figure, figure_unit, icon) VALUES
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 1,
   'Kuasa yang diukur dalam kilowatt',
   'Julat ini mencapai 6 kW pada tungku utama C830G, dan tujuh daripada sembilan dapur gas berada pada 4.8 kW atau lebih. Itu haba yang cukup untuk memanaskan kuali dengan cepat dan mengekalkannya di situ, iaitu tugas utama dapur gas di dapur Malaysia.',
   '6', 'kW', 'power'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 2,
   'Api berbilang gelang, haba di seluruh dasar kuali',
   'Gelang api dalam dan luar menyebarkan haba ke seluruh dasar kuali dan bukan hanya satu titik di tengah. C836G menerbitkan kecekapan tenaga 73% hasil reka bentuk itu, dan ia satu-satunya dapur dalam julat ini yang menyatakan angka tersebut.',
   '73', '%', 'heat'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 3,
   'Keselamatan sebagai standard, bukan tambahan',
   'Alat keselamatan pada setiap tungku gas memutuskan bekalan sebaik sahaja api padam. Pemutus kering bakar, pemutus terma, sensor tanpa periuk dan tombol berkunci kanak-kanak terdapat merentasi julat ini, dan kedua-dua dapur seramik menambah perlindungan panas lampau dan amaran haba baki.',
   NULL, NULL, 'safety'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 4,
   'Permukaan yang dibuat untuk dilap',
   'Kaca terbaja pada kebanyakan model, salutan nano pada C836G, dan keluli tahan karat gred tinggi pada Professional C720S. C861G pergi lebih jauh dan melipat tungkunya ke atas, jadi tiada apa-apa lagi yang perlu dibersihkan di sekelilingnya.',
   NULL, NULL, 'clean'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 5,
   'Pemasa yang memasak sementara anda membuat kerja lain',
   'Kawalan pemasa bebas sembilan puluh sembilan minit pada C822G, C830G dan C835G, kawalan api lapan kelajuan pada dapur AI, dan empat mod pratetap pada C861G untuk menumis, menggoreng, memanggang dan merebus.',
   NULL, NULL, 'smart'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 6,
   'Penyalaan yang menyala pada cubaan pertama',
   'Penyalaan sifar saat pada M822G dan C836G, penyalaan elektrik atau bateri untuk dapur yang tiada soket di belakang kaunter, dan panel sentuh penuh pada kedua-dua dapur seramik.',
   NULL, NULL, 'controls');

INSERT INTO category_faq (category_id, lang, position, question, answer_md) VALUES
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 1,
   'Di manakah dapur gas patut diletakkan?',
   'Di tempat yang mempunyai pengudaraan baik dan ruang lapang di sekelilingnya untuk periuk dan untuk orang yang memasak. Jauhkan daripada angin, dan pasang [hood dapur](/kitchen-hood-in-malaysia/) betul-betul di atasnya supaya asap ada jalan keluar.'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 2,
   'Saiz dapur gas yang bagaimana saya perlukan?',
   'Enam puluh sentimeter sesuai untuk masakan asas, tujuh puluh mengimbangi saiz dengan ruang kaunter, dan sembilan puluh sesuai untuk dapur yang besar. Ukur lubang potongan pada kaunter sebelum membeli: model Flexi menerima bukaan selebar 650 hingga 710 mm, yang meliputi kebanyakan lubang yang sedia ada.'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 3,
   'Berapa lama jangka hayat dapur gas?',
   'Sepuluh hingga lima belas tahun dengan penjagaan yang betul. Tungku dan pencucuh ialah alat ganti yang boleh diservis, jadi dapur jarang rosak sepenuhnya. Pastikan penutup tungku bersih dan lubang apinya tidak tersumbat, dan ia akan bertahan lebih lama daripada dapur tempat ia dipasang.'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 4,
   'Dapur gas kaca atau keluli tahan karat, mana yang lebih baik?',
   'Kaca kelihatan lebih kemas dan lebih cepat dilap. Keluli tahan karat lebih tahan haba dan calar, dan yang lebih lasak antara kedua-duanya. [Panduan membeli dapur gas](/buying-guide/glass-vs-stainless-gas-hob-which-gas-hob-are-best/) kami membandingkannya dengan teliti.'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 5,
   'Apa yang perlu dilihat semasa membeli dapur gas?',
   'Kuasa tungku, saiz lubang potongan, bilangan tungku, jenis kawalan dan ciri keselamatan. Ikut urutan itu: kuasa dan muatan menyingkirkan kebanyakan model sebelum perkara lain menjadi penting. Jika anda masih memilih antara gas dan elektrik, [panduan induksi atau seramik](/buying-guide/which-is-better-induction-or-ceramic-cooker/) kami menerangkan pilihan elektrik.'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 6,
   'Berapa jauh dapur gas perlu dari tingkap?',
   'Sekurang-kurangnya 100 cm sebagai peraturan umum, supaya pengudaraan berfungsi dengan betul dan angin tidak memadamkan api. Pemasang anda akan mengesahkannya mengikut susun atur dapur anda.'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 7,
   'Dapur gas yang mana lebih mudah dibersihkan?',
   'Kaca, kerana permukaannya rata dan tumpahan kekal di atasnya. [C836G](/vatti-flexi-hob-c836g/) menambah salutan nano yang menghalang gris melekat, dan [C861G](/vatti-magic-series-cooker-hob-c861g/) melipat tungkunya ke atas supaya anda boleh mengelap terus merentasinya.'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 8,
   'Kenapa makanan lebih sedap dimasak di atas dapur gas?',
   'Kerana haba bertindak balas serta-merta. Api bertukar dari besar ke kecil sebaik sahaja tombol dipusing, dan teknik menyalai serta memasak dengan kuali bergantung pada itu. [Perbandingan dapur induksi dan dapur gas](/buying-guide/induction-cooker-vs-gas-stove/) kami meletakkan kedua-duanya bersebelahan, dan panduan kami tentang [dapur gas inframerah](/buying-guide/is-an-infrared-gas-stove-worth-it/) menerangkan tungku plat merah menyala yang menyalurkan lebih banyak haba ke dalam kuali.'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 9,
   'Bagaimana saya boleh memanfaatkan dapur gas saya sepenuhnya?',
   'Padankan periuk dengan tungku: periuk kecil di atas tungku 6 kW menghantar kebanyakan haba ke tepinya. Bersihkan penutup tungku, pastikan lubang api tidak tersumbat, dan gunakan pemasa daripada memerhati jam.'),
  ((SELECT id FROM product_category WHERE slug = 'cooker-hob-in-malaysia'), 'ms-MY', 10,
   'Bolehkah saya memasang dapur gas sendiri?',
   'Bukan dapur gas. Dapur gas mesti dipasang oleh profesional, dan memasangnya sendiri tidak selamat serta boleh membatalkan waranti.');

-- ── ketuhar kombi ──────────────────────────────────────────────────────────
-- Nothing dropped. "Combi" stays as the loanword where it names the oven type.
INSERT INTO category_guide (category_id, lang, position, heading, body_md, figure, figure_unit) VALUES
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 1,
   'Stim ialah apa yang dapur Malaysia mahukan daripada ketuhar',
   'Kebanyakan ketuhar dibina untuk membakar. Kebanyakan masakan rumah di sini pula dikukus: nasi, ikan, pau, kuih, dan lauk semalam yang dipanaskan semula tanpa menjadi kering. VA05 dan VA06 mengukus pada tiga tahap, rendah, sederhana dan tinggi, dan kedua-duanya mempunyai mod nasi stim. VA06 menambah tiga mod rebusan, untuk bubur, daging dan sup.',
   '3', 'tahap stim'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 2,
   'Perolakan, stim, atau kedua-duanya serentak',
   'Perolakan mengedarkan udara panas untuk hasil yang rangup dan perang sekata. Stim mengekalkan kelembapan, jadi makanan kekal lembut. Ketuhar kombi menjalankan salah satu, atau kedua-duanya bersama: VA06 boleh memanggang stim dan membakar stim, dan VA05 mempunyai dua fungsi gabungan. Itulah yang membolehkan satu ruang memanggang ayam pada hari Ahad dan mengukus ikan pada hari Isnin.',
   NULL, NULL),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 3,
   'Tiga ketuhar bersaiz penuh dan sebuah ketuhar gelombang mikro',
   'Ketiga-tiga ketuhar berkapasiti 70 liter (VA05 dan VA06) dan 75 liter (O7559), cukup ruang untuk hidangan panggang keluarga berserta lauk sampingannya. M626 ialah ketuhar gelombang mikro terbina dalam 25L dengan gril, untuk memanaskan semula dan memasak dengan cepat, bukan untuk membakar. Tiada ketuhar padat dalam julat ini, jadi ukur bukaan kabinet sebelum memilih, bukan selepasnya.',
   '70-75', 'L'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 4,
   'Penggoreng udara yang sudah ada di dalam dinding',
   'Ketiga-tiga ketuhar boleh menggoreng udara, menggunakan kipas dan elemen yang sedia ada dalam ketuhar untuk merangupkan makanan dengan sedikit minyak atau tanpa minyak. O7559 disertakan dengan rak penggoreng udaranya sendiri, VA05 mempunyai fungsi penggoreng udara dan VA06 dua mod penggoreng udara. Jika isi rumah suka makanan bergoreng tetapi tidak mahu menggoreng dalam minyak banyak, itu satu perkakas kurang di atas kaunter.',
   NULL, NULL),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 5,
   'Kira fungsi yang benar-benar akan anda gunakan',
   'Ketuhar di sini menyenaraikan 9 hingga 12 fungsi memasak. Lebih banyak tidak semestinya lebih baik: mod membakar kedua yang tidak pernah anda pilih kurang bernilai berbanding tetapan stim yang memanaskan semula nasi tanpa mengeringkannya. Tentukan tiga fungsi yang akan anda gunakan dalam seminggu dan pilih berdasarkannya. VA05 dan VA06 juga mempunyai 68 menu masakan automatik untuk hari anda tidak mahu membuat keputusan.',
   '9-12', 'fungsi'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 6,
   'Apa yang ketuhar stim perlukan daripada anda',
   'Bahagian stim menggunakan tangki air, 1.3 liter pada VA06, jadi mengisinya ialah sebahagian daripada penggunaan, dan sistem stim perlu dinyahkerak mengikut jadual dalam manual, lebih kerap di kawasan air liat. Sebagai balasan, VA05 dan VA06 membersihkan diri sendiri: kitaran pembersihan stim melonggarkan kotoran pada dinding, dan kitaran pengeringan haba memastikan ruang kering, bukan basah.',
   NULL, NULL);

INSERT INTO category_reason (category_id, lang, position, title, body_md, figure, figure_unit, icon) VALUES
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 1,
   'Perolakan dan stim dalam satu ruang',
   'Udara panas untuk luaran yang rangup, stim terkawal untuk dalaman yang lembap, dan kedua-duanya bersama apabila sesuatu hidangan memerlukannya. Pada VA05 dan VA06, itu satu perkakas, satu bukaan dalam deretan kabinet dan satu benda untuk dibersihkan, yang melakukan kerja ketuhar dan pengukus.',
   NULL, NULL, 'heat'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 2,
   'Stim yang anda tetapkan, bukan stim yang anda harapkan',
   'Tiga tahap stim pada VA05 dan tiga gred kelembapan pada VA06, jadi ikan yang halus dan sedulang pau mendapat jumlah stim yang berbeza. Kawalan suhu dwi pada kedua-duanya mengasingkan suhu bahagian atas dan bawah ketuhar semasa memasak.',
   '3', 'tahap stim', 'water'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 3,
   'Nasi, bubur dan yogurt juga',
   'Kedua-dua ketuhar kombi boleh menanak nasi stim, menaikkan doh, membuat yogurt, memanaskan makanan dan menyahbeku. VA06 menambah mod rebusan bubur, daging dan sup. Kerja yang biasanya memerlukan periuk nasi, periuk perlahan dan pengukus, semuanya dari satu ruang.',
   NULL, NULL, 'controls'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 4,
   'Enam puluh lapan menu yang boleh anda abaikan',
   'VA05 dan VA06 mempunyai 68 menu masakan automatik, dan VA05 menambah program stim berbilang peringkat yang bertukar di tengah-tengah masakan. Gunakannya, atau tetapkan sendiri. Kedua-duanya pada panel yang sama.',
   '68', 'menu', 'smart'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 5,
   'Bersih dengan stim, kemudian kering sendiri',
   'Dua fungsi pembersihan automatik pada VA05 dan VA06: stim untuk melonggarkan kotoran pada dinding, kemudian haba untuk mengeringkan ruang supaya tidak dibiarkan basah. O7559 mempunyai ruang enamel yang mudah dilap, dan M626 mempunyai fungsi pembersihan automatiknya sendiri.',
   NULL, NULL, 'clean'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 6,
   'Pintu yang selamat untuk berdiri di sebelahnya',
   'Pintu kaca tiga lapis pada ketiga-tiga ketuhar memastikan bahagian luar cukup sejuk untuk dibuka walaupun ada kanak-kanak di dapur. Pintu O7559 boleh ditanggalkan untuk dibersihkan tanpa alat.',
   '3', 'lapisan kaca', 'safety');

INSERT INTO category_faq (category_id, lang, position, question, answer_md) VALUES
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 1,
   'Bilakah anda menggunakan ketuhar kombi?',
   'Setiap kali anda menggunakan ketuhar, dan sebagai ganti pengukus juga. Ia membakar, memanggang, menggril dan mengukus, yang meliputi kebanyakan kerja ketuhar dalam seminggu, dari ayam panggang hingga ikan dan nasi kukus.'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 2,
   'Berapa lama jangka hayat ketuhar kombi terbina dalam?',
   'Lapan hingga sepuluh tahun dengan penjagaan yang betul. Menyahkerak sistem stim mengikut jadual ialah bahagian yang sering dilupakan, dan bahagian itulah yang menentukan sama ada anda mendapat lapan atau sepuluh tahun.'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 3,
   'Adakah ketuhar kombi sama dengan ketuhar stim?',
   'Ia mengandungi satu. Ketuhar kombi menggunakan haba perolakan kering dan stim, secara berasingan atau bersama, jadi ia melakukan semua yang dilakukan ketuhar stim khusus dan boleh membakar juga. [VA05](/built-in-combi-oven-va05/) dan [VA06](/vatti-magic-series-combi-oven-va06/) kedua-duanya ketuhar kombi; julat VATTI sekarang tiada ketuhar stim sahaja.'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 4,
   'Adakah ketuhar kombi juga penggoreng udara?',
   'Biasanya tidak, tetapi dua di sini boleh. [VA05](/built-in-combi-oven-va05/) dan [VA06](/vatti-magic-series-combi-oven-va06/) kedua-duanya mempunyai mod penggoreng udara di samping fungsi membakar dan stim, dan O7559 disertakan dengan rak penggoreng udaranya sendiri.'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 5,
   'Apakah julat suhu ketuhar kombi terbina dalam?',
   'Ketuhar kombi biasanya beroperasi dari sekitar 85°C hingga 275°C, meliputi proses menaikkan doh secara perlahan di hujung bawah dan panggang panas di hujung atas. Semak halaman produk untuk model yang anda lihat.'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 6,
   'Apakah penjagaan yang diperlukan oleh ketuhar kombi?',
   'Pembersihan berkala, menyahkerak sistem stim, dan memeriksa getah pintu. Setiap tiga hingga enam bulan ialah selang yang sesuai untuk menyahkerak dengan air di Malaysia.'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 7,
   'Adakah ketuhar kombi memerlukan air?',
   'Ya, untuk bahagian stim. Model ini mempunyai tangki sendiri dan tidak memerlukan sambungan paip, 1.3 liter pada VA06, jadi mengisinya ialah sebahagian daripada penggunaan fungsi stim.'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 8,
   'Apakah perbezaan antara ketuhar perolakan dan ketuhar kombi?',
   'Ketuhar perolakan hanya mengedarkan udara panas yang kering. Ketuhar kombi menambah stim, dan itulah yang menghalang hidangan yang dipanaskan semula daripada kering serta menjadikan daging panggang rangup di luar tetapi lembap di dalam. [Panduan ketuhar kombi](/buying-guide/what-is-a-combi-oven/) kami menerangkannya dengan lengkap, dan [simbol ketuhar dan maksudnya](/tips-tricks/oven-symbols-and-meanings/) menerangkan fungsi setiap ikon mod.'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 9,
   'Adakah ketuhar kombi memasak lebih cepat?',
   'Selalunya, ya. Stim memindahkan haba dengan lebih cekap berbanding udara kering, jadi program kombi boleh mencapai hasil yang sama dalam masa yang lebih singkat berbanding perolakan sahaja.'),
  ((SELECT id FROM product_category WHERE slug = 'combi-and-steam-oven-in-malaysia'), 'ms-MY', 10,
   'Perlukah ketuhar kombi dipanaskan dahulu?',
   'Ya, untuk apa sahaja yang hasilnya bergantung pada suhu ketika makanan dimasukkan, iaitu kebanyakan masakan bakar dan semua masakan panggang. Menu masakan automatik menguruskan pemanasan awal sebagai sebahagian daripada program. Panduan kami tentang [berapa lama memanaskan ketuhar](/tips-tricks/how-long-to-preheat-oven/) memberi masanya mengikut suhu.');

-- ── mesin basuh pinggan ────────────────────────────────────────────────────
-- Guide 6 drops "pre-rinsing is where the water people think they are saving
-- actually goes" (a water claim); the advice to scrape rather than rinse stays.
INSERT INTO category_guide (category_id, lang, position, heading, body_md, figure, figure_unit) VALUES
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 1,
   'Ikut saiz hidangan, bukan saiz dapur',
   'Satu tetapan tempat ialah kira-kira apa yang digunakan oleh seorang untuk satu hidangan. Kedua-dua mesin basuh pinggan VATTI ialah mesin besar: 17 tetapan pada DWBB7, 20 serta bakul buah dan sayur pada DWID3. VATTI mengira satu muatan penuh DWID3 sebanyak 130 keping, termasuk lapan belas mangkuk nasi, sembilan mangkuk mi dan 36 pasang penyepit. Itu untuk isi rumah empat orang atau lebih, atau keluarga yang sering menerima tetamu, dibasuh sekali sehari. Untuk seorang atau dua orang, mesin padat lebih sesuai, dan VATTI tidak membuatnya.',
   '17-20', 'tetapan tempat'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 2,
   'Haba yang menanggalkan minyak kuali',
   'Kedua-dua mesin membasuh pada 75°C. Air sepanas itu menanggalkan minyak masakan dari pinggan dan bukan sekadar mengalihkannya, dan ia terlalu panas untuk tangan, iaitu perkara yang tidak dapat ditandingi basuhan tangan walau selama mana anda menyental. DWBB7 kemudian mengeringkan dengan udara 110°C dan DWID3 dengan 105°C, jadi pinggan keluar tanpa kesan tuala.',
   '75', '°C'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 3,
   'Kering antara basuhan, di dapur yang lembap',
   'Mesin basuh pinggan yang dibiarkan tertutup dan lembap ialah punca bau, dan dapur Malaysia memberi setiap peluang untuk itu. Selepas kitaran, kedua-dua mesin terus mengalirkan udara melaluinya sehingga 168 jam. DWID3 menukar udaranya setiap tiga jam dan menyalakan lampu UVC ketika itu, jadi muatan bersih yang dibiarkan di dalam kekal segar sehingga tujuh hari dengan pintu tertutup.',
   '7', 'hari'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 4,
   'Periuk, bukan pinggan sahaja',
   'Masakan Asia mengotorkan periuk sama banyak dengan pinggan, jadi lihat rak bawah sebelum senarai program. Cucuk rak bawah DWID3 boleh dilipat rata untuk memuatkan sehingga empat periuk sekali gus, dan sekali tarik pada pemegangnya menurunkan rak untuk memuatkan periuk setinggi 30 cm. DWBB7 mempunyai program intensif untuk minyak dan satu untuk barang besar.',
   NULL, NULL),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 5,
   'Terbina dalam atau berdiri sendiri',
   'Mesin terbina dalam dipasang dalam deretan kabinet dan memberi kemasan paling kemas, jadi itulah yang perlu dirancang untuk dapur yang sedang dibina atau diubah suai. DWID3 bersepadu sepenuhnya dan selebar 60 cm, dibuat untuk bukaan kabinet 600 x 780 x 580 mm, jadi ukur bukaan sebelum memilih, bukan selepasnya. Mesin berdiri sendiri boleh diletakkan di mana-mana yang ada sumber air, saluran pembuangan dan soket.',
   NULL, NULL),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 6,
   'Jalankan dengan muatan penuh, dan kikis tanpa membilas',
   'Mesin basuh pinggan paling berbaloi dengan muatan penuh. Kikis sisa makanan ke dalam tong sampah dan tidak perlu membilas pinggan di bawah paip dahulu. Pada hari muatan penuh tidak berbaloi untuk ditunggu, kedua-dua mesin boleh menjalankan separuh muatan di bakul atas atau bawah sahaja. DWID3 juga menyukat detergennya sendiri, dari takungan yang tahan kira-kira dua minggu.',
   NULL, NULL);

INSERT INTO category_reason (category_id, lang, position, title, body_md, figure, figure_unit, icon) VALUES
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 1,
   'Ruang untuk dua puluh',
   'DWID3 memuatkan 20 tetapan tempat serta bakul buah dan sayur dalam tab 150 L, dan DWBB7 memuatkan 17. Pinggan mangkuk sehari untuk keluarga besar, atau makan malam bersama tetamu, dalam satu kitaran.',
   '20', 'tetapan tempat', 'clean'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 2,
   'Membasuh pada 75°C, mengering sehingga 110°C',
   'Cukup panas untuk menanggalkan minyak masakan dari pinggan, kemudian cukup panas untuk mengeringkannya tanpa kesan tuala. Kedua-dua mesin juga boleh mengering secara berasingan, jadi muatan yang dibasuh tangan atau sekumpulan botol boleh dikeringkan tanpa basuhan kedua.',
   '75', '°C', 'heat'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 3,
   'Disteril, kemudian kekal steril',
   'Basuhan suhu tinggi, pengeringan udara panas dan lampu UVC selepas kedua-duanya, yang dinilai VATTI sehingga 99.9% pada DWID3. Kemudian pengudaraan sehingga 168 jam, jadi muatan yang siap menunggu dalam keadaan kering, bukan lembap.',
   '168', 'jam', 'safety'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 4,
   'Motor tanpa berus, dan 55,000 Pa',
   'Kedua-dua mesin menggunakan motor BLDC, yang mengekalkan tekanan semburan pada kelajuan lebih rendah. DWID3 menggunakannya untuk memacu pam tekanan boleh ubah sehingga 55,000 Pa melalui dua lengan semburan teleskopik yang sampai ke penjuru tab, bukan hanya bulatan di tengah.',
   '55,000', 'Pa', 'motor'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 5,
   'Program untuk buah, mainan dan botol',
   'Selain kitaran harian, kedua-dua mesin mempunyai program untuk buah dan sayur, mainan kanak-kanak dan botol susu, serta kitaran pembersihan sendiri untuk mesin itu. DWBB7 mempunyai lapan kesemuanya; DWID3 mempunyai enam program utama dan empat lagi dalam aplikasi.',
   NULL, NULL, 'water'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 6,
   'DWID3 menjaga dirinya sendiri',
   'Detergen disukat mengikut tahap kekotoran dari takungan dua minggu, saluran pembuangan yang mengedap sendiri apabila selesai, dua pam yang tidak meninggalkan air bertakung di dalam takungan, dan panel sentuh 23 inci dengan kawalan yang sama dalam aplikasi VATTI.',
   NULL, NULL, 'smart');

INSERT INTO category_faq (category_id, lang, position, question, answer_md) VALUES
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 1,
   'Adakah mesin basuh pinggan berbaloi di rumah Malaysia?',
   'Untuk isi rumah empat orang atau lebih yang memasak dengan minyak hampir setiap hari, ya. Ia membasuh pada 75°C, yang tidak mampu dilakukan tangan, jadi ia membersihkan pinggan berminyak dengan lebih baik dan mensanitasinya sekali gus, dan ia memulangkan masa yang dihabiskan di sinki selepas setiap hidangan. Untuk seorang atau dua orang yang kerap makan di luar, ia lebih sukar untuk dijustifikasikan. Jawapan panjangnya dalam [adakah mesin basuh pinggan berbaloi](/buying-guide/is-a-dishwasher-worth-it/).'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 2,
   'Berapa banyak tetapan tempat yang saya perlukan?',
   'Kira-kira satu bagi setiap orang untuk setiap hidangan, dengan ruang untuk periuk. Kedua-dua mesin VATTI bersaiz untuk isi rumah yang besar: 17 tetapan tempat pada DWBB7 dan 20 pada DWID3, yang dikira VATTI sebagai 130 keping dalam muatan penuh. Untuk kebanyakan keluarga besar, itu satu kitaran sehari.'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 3,
   'Bolehkah mesin basuh pinggan membersihkan pinggan kuali yang berminyak?',
   'Ya, dan lebih baik daripada basuhan tangan. Air pada 75°C, detergen mesin basuh pinggan dan program intensif memecahkan minyak masakan jauh lebih berkesan daripada air paip suam dan span. Kikis sisa makanan dahulu; tidak perlu membilas.'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 4,
   'Bolehkah mesin basuh pinggan membasuh periuk dan kuali?',
   'Kebanyakannya. Periuk dan kuali keluli tahan karat diletakkan di rak bawah, dan pada DWID3 cucuk rak boleh dilipat rata untuk sehingga empat periuk dan rak boleh diturunkan untuk memuatkan periuk setinggi 30 cm. Besi tuang, pemegang kayu dan mana-mana kuali yang pembuatnya menyatakan basuh tangan perlu dikecualikan: lihat [apa yang tidak selamat untuk mesin basuh pinggan](/tips-tricks/what-is-not-dishwasher-safe/).'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 5,
   'Terbina dalam atau berdiri sendiri untuk dapur Malaysia?',
   'Terbina dalam jika dapur sedang dibina atau diubah suai: ia bersepadu dengan kabinet dan memberi kapasiti terbaik untuk ruang itu. Berdiri sendiri jika dapur sudah siap dan tiada kabinet yang boleh dikorbankan, kerana ia hanya memerlukan sumber air, saluran pembuangan dan soket.'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 6,
   'Adakah mesin basuh pinggan membunuh bakteria?',
   'Haba melakukan kebanyakannya: basuhan 75°C, kemudian pengeringan pada 105°C pada DWID3 dan 110°C pada DWBB7. Kedua-duanya menambah lampu UVC selepas basuhan, yang merosakkan DNA bakteria supaya ia tidak dapat membiak; VATTI menilai lampu DWID3 sehingga 99.9%. Ini pensterilan fizikal, tanpa sebarang bahan kimia tertinggal di pinggan.'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 7,
   'Adakah muatan yang bersih akan berbau jika saya biarkan di dalam mesin?',
   'Tidak dengan mesin ini. Selepas kitaran, kedua-dua mesin terus mengalirkan udara melaluinya sehingga 168 jam, dan DWID3 menyalakan lampu UVC mengikut pemasa, jadi muatan yang dibiarkan di dalam kekal kering dan segar sehingga tujuh hari. Pinggan kotor yang menunggu kitaran malam ialah soalan yang berbeza: lihat [membiarkan pinggan dalam mesin basuh pinggan semalaman](/tips-tricks/dishes-in-the-dishwasher-overnight/).'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 8,
   'Bolehkah mesin basuh pinggan digunakan setiap hari?',
   'Ya. Penggunaan harian ialah tujuan mesin ini dibina. Pastikan penapis bersih dan jalankan kitaran pembersihan sendiri setiap satu atau dua bulan, dan penggunaan harian tidak memendekkan apa-apa. DWID3 membilas penapisnya sendiri semasa membuang air, dan aplikasinya mengingatkan anda apabila pembersihan sendiri perlu dijalankan.'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 9,
   'Bolehkah mesin basuh pinggan membasuh buah dan sayur?',
   'Kedua-dua mesin ini boleh. Kedua-duanya mempunyai program buah. Program DWID3 berjalan selama 26 minit dalam air lembut dengan bakul khas yang disertakan, dan VATTI mengukurnya menyingkirkan 95% sisa racun perosak. Anggur dan beri mendapat basuhan bergolek yang lembut, bukan semburan kuat.'),
  ((SELECT id FROM product_category WHERE slug = 'dishwasher-in-malaysia'), 'ms-MY', 10,
   'Berapa lama jangka hayat mesin basuh pinggan yang baik?',
   'Sepuluh hingga lima belas tahun, bergantung pada kekerapan penggunaan dan sejauh mana penapis dijaga. [Panduan membeli mesin basuh pinggan](/buying-guide/is-a-dishwasher-necessary/) kami menerangkan perkara yang perlu dilihat sebelum membelinya.');

-- ── penapis air ────────────────────────────────────────────────────────────
-- Guide 6 is retitled from "Filters are the running cost" and drops "budget
-- for replacements, and have the dealer do the first change" (running cost,
-- installation arrangement). FAQ 3 drops "use a professional installer"
-- (who installs); FAQ 8 drops "the filters are a running cost"; FAQ 9 drops
-- "what the replacement filters cost over a few years".
INSERT INTO category_guide (category_id, lang, position, heading, body_md, figure, figure_unit) VALUES
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 1,
   'Empat suhu dari satu paip',
   'Sejuk untuk minum, suhu bilik, 45°C, dan 100°C untuk teh, kopi dan mi segera. Tetapan 45°C bukan sekadar anggaran "suam": itulah suhu untuk membancuh susu formula bayi, dan sebab itulah isi rumah yang mempunyai bayi membeli penapis seperti ini.',
   '45-100', '°C'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 2,
   'Aliran yang cukup untuk mengisi periuk',
   'Keluaran di paip ialah 1.5 liter seminit, jadi jag satu liter penuh dalam kira-kira empat puluh saat. Itulah bezanya penapis yang digunakan dapur untuk memasak dengan penapis yang hanya mengisi gelas.',
   '1.5', 'L/min'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 3,
   'Apa yang disingkirkan oleh osmosis songsang',
   'RO menolak air melalui membran yang cukup halus untuk menahan logam berat, klorin dan pepejal terlarut. Ia turut menyingkirkan sebahagian mineral semula jadi, yang biasa bagi kaedah ini dan tidak menjadikan air kurang selamat untuk diminum.',
   NULL, NULL),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 4,
   'Peringkat sebelum membran',
   'Sistem VPC menjalankan peringkat sedimen dan karbon teraktif sebelum membran RO. Ia menyingkirkan zarah dan rasa klorin terlebih dahulu, dan dengan itu juga menghalang membran di belakangnya daripada tersumbat terlalu awal.',
   NULL, NULL),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 5,
   'Ia duduk di bawah sinki',
   'Unit penapisan dan tangki dimuatkan ke dalam kabinet di bawah. Yang kelihatan di atas kaunter hanyalah paip keluli tahan karat SUS 304 yang ramping, sebab itu ia sesuai untuk dapur kondominium yang tidak muat dispenser berdiri dan botolnya.',
   NULL, NULL),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 6,
   'Hayat penapis dijejak untuk anda',
   'Unit ini menjejak hayat penapis dan memberitahu anda apabila penapis perlu ditukar, tanpa bergantung pada ingatan. Ini penting kerana penapis yang melepasi hayatnya ialah penapis air yang diam-diam berhenti menapis.',
   NULL, NULL);

INSERT INTO category_reason (category_id, lang, position, title, body_md, figure, figure_unit, icon) VALUES
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 1,
   'Pelbagai peringkat dahulu, kemudian RO',
   'Sedimen dan karbon teraktif menyingkirkan zarah dan klorin. Membran osmosis songsang di belakangnya menyingkirkan selebihnya: logam berat, bakteria dan pepejal terlarut.',
   NULL, NULL, 'filtration'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 2,
   'Air mendidih bila-bila masa',
   'Terus 100°C di paip, tanpa cerek untuk diisi dan tanpa menunggu. Inilah tetapan yang diam-diam mengeluarkan satu perkakas dari kaunter.',
   '100', '°C', 'heat'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 3,
   'Empat suhu, satu kelengkapan',
   'Sejuk, suhu bilik, 45°C dan 100°C, dipilih di paip. Satu kelengkapan menggantikan dispenser, cerek dan jag di pintu peti sejuk.',
   '4', 'mod', 'water'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 4,
   'Keluli tahan karat di tempat air berada',
   'Paip dan tangki kedua-duanya keluli tahan karat SUS 304, bukan plastik. Dalam sistem yang menyimpan air pada 100°C, itulah yang memastikan air tidak berasa apa-apa.',
   NULL, NULL, 'safety'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 5,
   'Ia memberitahu bila penapis perlu ditukar',
   'Peringatan penukaran penapis pada paparan. Perkara yang menentukan sama ada air benar-benar ditapis tidak lagi bergantung pada seseorang mengingati bila kali terakhir ia ditukar.',
   NULL, NULL, 'smart'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 6,
   'Tiada apa-apa di atas kaunter',
   'Keseluruhan sistem berada di bawah sinki. Di dapur kondominium, permukaan kerja ialah ruang paling terhad, dan ini memulangkan sudut yang sepatutnya diambil oleh dispenser.',
   NULL, NULL, 'clean');

INSERT INTO category_faq (category_id, lang, position, question, answer_md) VALUES
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 1,
   'Adakah penapis air satu paip lebih baik daripada dispenser air?',
   'Untuk kebanyakan rumah, ya. Ia menapis dan mengeluarkan air pada empat suhu dari satu kelengkapan di sinki, tanpa botol untuk diisi semula, tanpa mengambil ruang lantai, dan tanpa menunggu air dipanaskan atau disejukkan.'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 2,
   'Adakah osmosis songsang menyingkirkan mineral?',
   'Sebahagiannya, ya. RO cukup teliti sehingga ia turut menyingkirkan mineral semula jadi bersama logam berat, klorin dan pepejal terlarut. Itu biasa bagi kaedah ini, dan air kekal selamat untuk diminum. Panduan kami tentang [apa itu air osmosis songsang](/tips-tricks/what-is-reverse-osmosis-water/) menerangkan kebaikan dan kelemahannya dengan lengkap.'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 3,
   'Bolehkah ia dipasang di bawah sinki?',
   'Di situlah ia direka untuk dipasang. Unit penapisan dan tangki dimuatkan ke dalam kabinet di bawah dan hanya paip yang kelihatan di atas.'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 4,
   'Bolehkah saya menulenkan air paip dengan merebusnya?',
   'Sebahagian sahaja. Merebus membunuh kebanyakan bakteria, tetapi tidak berbuat apa-apa terhadap bahan kimia, logam berat atau sedimen, malah memekatkannya dan bukan menyingkirkannya. [Panduan cara penapis air berfungsi](/buying-guide/how-water-filters-work/) kami menerangkan perbezaannya.'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 5,
   'Adakah air paip selamat diminum di Malaysia?',
   'Ia dirawat mengikut piawaian selamat apabila meninggalkan loji. Apa yang berlaku antara loji dan paip anda berbeza-beza: paip lama, pencemaran setempat dan perubahan musim semuanya mempengaruhi air yang sampai.'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 6,
   'Perlukah saya benar-benar menapis air paip?',
   'Jika air berasa atau berbau sesuatu, jika bangunan sudah lama, atau jika ada bayi di rumah, ya. Selain itu, ia bergantung pada sejauh mana anda mahu memikirkannya.'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 7,
   'Apakah tanda-tanda air paip yang tidak selamat?',
   'Rasa atau bau yang tidak elok, air keruh atau berubah warna, sedimen yang kelihatan, dan sakit perut selepas meminumnya. Mana-mana satu daripadanya ialah sebab untuk berhenti meminumnya tanpa ditapis dan mencari puncanya.'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 8,
   'Apakah kelemahan penapis air?',
   'Penapis perlu ditukar tepat pada masanya. Sistem RO juga menyalurkan sebahagian air ke saluran pembuangan sebagai sebahagian daripada cara membran berfungsi. Kedua-duanya ialah harga untuk ketulenan, dan baik diketahui sebelum membeli, bukan selepasnya.'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 9,
   'Apa yang perlu dipertimbangkan semasa membeli penapis air?',
   'Kualiti air yang masuk, jenis penapisan, dan berapa banyak air yang benar-benar diminum dan digunakan untuk memasak oleh isi rumah anda.'),
  ((SELECT id FROM product_category WHERE slug = 'one-tap-purifier-in-malaysia'), 'ms-MY', 10,
   'Kenapa air osmosis songsang terasa tawar?',
   'Kerana ia sangat tulen dan rendah mineral, dan mineral ialah sebahagian besar rasa air. Ia soal kebiasaan, bukan kerosakan.');

